import {utcDay,dateFromDay} from './cycle-engine.js?v=1.19.0';
import {createAssetJudgmentHistory,fingerprintComparisonBundle,HISTORY_NOTE,yieldHistoryTask} from './asset-judgment-history.js?v=1.28.0';
import {createSavedJudgmentLoader,savedJudgmentsCsv} from './asset-judgment-records.js?v=1.28.0';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=v=>typeof v==='number'&&Number.isFinite(v)?`${v>0?'+':v<0?'−':''}${Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}%`:'—';
const num=v=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:4}):'—';
const LABELS={'strong-buy':'적극 매수',buy:'분할 매수',neutral:'중립',sell:'분할 매도','strong-sell':'적극 매도',unavailable:'판단 보류','calculation-error':'계산 확인'};
const COLORS={'strong-buy':'#83ddbc',buy:'#3b9278',neutral:'#b6a15c',sell:'#a96976','strong-sell':'#f0a6b2',unavailable:'#4b5659','calculation-error':'#c5a98a'};
const groups=['위험 자산','안전 자산','대체자산'];
const csvCell=v=>{if(v==null||typeof v==='number'&&!Number.isFinite(v))return '';let t=String(v);if(typeof v!=='number'&&(/^[\u0000-\u0020]*[=+\-@]/.test(t)||/^[\t\r]/.test(t)))t="'"+t;return /[",\r\n]/.test(t)?'"'+t.replaceAll('"','""')+'"':t;};
function shiftYear(date,n){const[y,m,d]=date.split('-').map(Number),last=new Date(Date.UTC(y-n,m,0)).getUTCDate();return `${y-n}-${String(m).padStart(2,'0')}-${String(Math.min(d,last)).padStart(2,'0')}`;}
export function clippedHistoryRuns(runs,start,end){return runs.filter(r=>r.end>=start&&r.start<=end).map(r=>({...r,start:r.start<start?start:r.start,end:r.end>end?end:r.end}));}
export function historyGradient(runs,start,end){const lo=utcDay(start),length=utcDay(end)-lo+1;return `linear-gradient(to right, ${runs.map(r=>`${COLORS[r.id]||COLORS.unavailable} ${((utcDay(r.start)-lo)/length*100).toFixed(5)}% ${((utcDay(r.end)-lo+1)/length*100).toFixed(5)}%`).join(',')||'#4b5659 0% 100%'})`;}
export async function reconstructedHistoryCsv(index,{symbol,startDate,endDate,signal}={}){
  if(!index.assets.some(a=>a.symbol===symbol))throw new TypeError('CSV 종목을 확인해 주세요.');
  const fields=['kind','source_version','as_of_utc','observation_date','symbol','name','group','judgment_id','judgment','reason','sample_years','mean_annual_rise_pct','mean_annual_fall_pct_not_mdd','year_start_date','year_start_close','latest_close','year_to_date_pct','source_retrieved_at'];
  const lines=[fields.join(',')];let count=0;
  for(const r of index.dailyRows({symbol,startDate,endDate})){
    if(signal?.aborted)throw new DOMException('Export cancelled','AbortError');
    lines.push(['reconstructed',index.sourceVersion,r.asOf,r.latestDate,r.symbol,r.name,r.group,r.judgment.id,r.judgment.label,r.judgment.reason,r.sampleYears,r.meanRisePct,r.meanFallPct,r.yearStartDate,r.yearStartPrice,r.latestPrice,r.ytdPct,r.source.retrievedAt].map(csvCell).join(','));
    if(++count%512===0)await yieldHistoryTask();
  }
  return '\uFEFF'+lines.join('\r\n')+'\r\n';
}
function frame(){return `<div class="asset-history-heading"><div><p>ASSET JUDGMENT ARCHIVE</p><h2 id="asset-history-title">판단 이력</h2></div><button type="button" id="asset-history-close" aria-label="판단 이력 닫기">×</button></div><nav class="asset-history-mode" aria-label="이력 종류"><button type="button" data-history-mode="reconstructed" aria-pressed="true">과거 재계산</button><button type="button" data-history-mode="saved" aria-pressed="false">실제 저장 스냅샷</button></nav><p class="asset-history-disclosure" id="history-disclosure"></p><div id="history-state" role="status" aria-live="polite"></div><div id="history-toolbar" hidden><nav class="asset-history-groups" aria-label="자산군 선택"><button type="button" data-history-group="all" aria-pressed="true">전체</button>${groups.map(g=>`<button type="button" data-history-group="${g}" aria-pressed="false">${g}</button>`).join('')}</nav><div class="asset-history-range" id="history-range-controls"><nav aria-label="표시 기간"><button type="button" data-history-range="1" aria-pressed="true">1년</button><button type="button" data-history-range="5" aria-pressed="false">5년</button><button type="button" data-history-range="all" aria-pressed="false">전체 기간</button></nav><div class="asset-history-date-control"><label>판단 기준일 <span>UTC</span><input type="date" id="history-date"></label><div class="asset-history-day-moves"><button type="button" id="history-prev" aria-label="이전 기준일">←</button><button type="button" id="history-next" aria-label="다음 기준일">→</button></div></div></div><div id="history-slider-wrap"><input type="range" id="history-slider" aria-label="이력 기준일 이동"><div class="asset-history-date-ends"><span id="history-start"></span><span id="history-end"></span></div></div><div class="asset-history-legend" id="history-legend" aria-label="판단 색상">${Object.entries(LABELS).map(([id,label])=>`<span><i style="background:${COLORS[id]}" aria-hidden="true"></i>${label}</span>`).join('')}</div></div><div id="history-body"></div><section id="history-detail"></section><details class="asset-history-method"><summary>이력의 기준과 한계</summary><p>${HISTORY_NOTE}</p><p>판단 기준일과 실제 종가 관측일은 다릅니다. 휴장일에는 마지막 관측을 참조하며, 새 종가가 생긴 것으로 표시하지 않습니다. 당시 장 마감 시각의 이용 가능성이나 거래 수익률을 검증한 기록이 아닙니다. 자산군은 개별 종목을 묶어 보여줄 뿐, 합성 매수·매도 신호를 만들지 않습니다.</p><p>현재 시점에 알려진 공급자 보정·분할 반영·결측 정보가 재계산에 포함될 수 있습니다. 실제 저장 스냅샷은 저장 시각의 계산 결과이며 배포 성공이나 거래 실행을 증명하지 않습니다.</p></details>`;}

/** Lazy bounded view; closes/invalidation cancel work without replaying requests. */
