  const $=s=>root.querySelector(s),put=(s,v)=>{const e=$(s);if(e.innerHTML!==v)e.innerHTML=v;},text=(s,v)=>{const e=$(s);if(e.textContent!==v)e.textContent=v;};
  const state={mode:'reconstructed',group:'all',range:'1',symbol:'BTC',date:'',page:0,savedPage:30,index:null,saved:null,record:null};
  let cache=null,token=0,abort=null,disposed=false,exporting=false,lastOpen=null;
  const status=v=>text('#history-state',v);
  function controls(){for(const b of root.querySelectorAll('[data-history-group]'))b.setAttribute('aria-pressed',String(b.dataset.historyGroup===state.group));for(const b of root.querySelectorAll('[data-history-mode]'))b.setAttribute('aria-pressed',String(b.dataset.historyMode===state.mode));for(const b of root.querySelectorAll('[data-history-range]'))b.setAttribute('aria-pressed',String(b.dataset.historyRange===state.range));$('#history-range-controls').hidden=state.mode!=='reconstructed';$('#history-slider-wrap').hidden=state.mode!=='reconstructed';$('#history-legend').hidden=state.mode!=='reconstructed';}
  function range(){const end=cache.index.endDate,start=state.range==='all'?cache.index.startDate:[cache.index.startDate,shiftYear(end,Number(state.range))].sort().at(-1);return {start,end};}
