    const selected=rows.find(r=>r.symbol===state.symbol);if(!selected){put('#history-detail','');return;}
    const runs=clippedHistoryRuns(cache.runs.assets.find(a=>a.symbol===state.symbol).runs,start,end).reverse(),visible=runs.slice(state.page,state.page+30);
    put('#history-detail',`<div class="asset-history-detail-heading"><div><h3 id="history-detail-title" tabindex="-1">${esc(selected.name)} <span>${esc(selected.symbol)}</span></h3><p>재계산 기준일 ${esc(state.date)} · 종가 관측일 ${esc(selected.latestDate||'관측 없음')}</p></div><button type="button" id="history-export" ${exporting?'disabled':''}>${esc(selected.symbol)} 일별 CSV</button></div><dl class="asset-history-metrics"><div><dt>재계산 판단</dt><dd class="asset-history-state-${selected.judgment.id}">${esc(selected.judgment.label)}</dd></div><div><dt>연초 대비 등락률</dt><dd>${pct(selected.ytdPct)}</dd></div><div><dt>연초→최고 종가 평균 상승률</dt><dd>${pct(selected.meanRisePct)}</dd></div><div><dt>연초→최저 종가 평균 하락률</dt><dd>${pct(selected.meanFallPct)}</dd></div></dl><p class="asset-history-reason">${esc(selected.judgment.reason)} · 분석 ${selected.sampleYears}개 연도${selected.samplePartialFirstYear?' · 첫해 일부 기간 포함':''}</p><h4>판단 유지 구간 <span>${runs.length}개 · 최근순</span></h4><ol class="asset-history-events">${visible.map(r=>`<li><span>${esc(r.start)}<small>— ${esc(r.end)}</small></span><strong class="asset-history-state-${r.id}">${esc(r.label)}</strong><p>${esc(r.reason)}</p></li>`).join('')}</ol><nav class="asset-history-pagination" aria-label="판단 구간 페이지">${state.page?'<button type="button" id="history-newer">← 더 최근 구간</button>':''}<span>${state.page+1}–${Math.min(state.page+30,runs.length)} / ${runs.length}</span>${runs.length>state.page+30?'<button type="button" id="history-more">더 이전 구간 →</button>':''}</nav><p class="asset-history-source">원자료 버전 <code>${esc(cache.sourceVersion.slice(0,16))}</code> · CSV는 선택 종목·표시 기간의 모든 달력일을 포함합니다.</p>`);
